const inputItems = $input.all();
const outputItems = [];

for (const item of inputItems) {
  const fullText = $('MSG_CLEAN').first().json.output || '';

  // Divide o texto por blocos separados por linha em branco dupla
  const blocks = fullText
    .split(/\r?\n\r?\n/)
    .map(p => p.trim())
    .filter(p => p);

  for (const block of blocks) {
    if (block) {
      outputItems.push({
        json: {
          segment: block
        }
      });
    }
  }
}

return outputItems;
